    38  NcpBase::PropertyHandler NcpBase::FindGetPropertyHandler(spinel_prop_key_t aKey)
    39  {
    40      NcpBase::PropertyHandler handler;
    41
    42      switch (aKey)
    43      {
    44          // --------------------------------------------------------------------------
    45          // Common Properties (Get Handler)
    46
    47      case SPINEL_PROP_CAPS:
    48          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_CAPS>;
    49          break;
    50      case SPINEL_PROP_DEBUG_TEST_ASSERT:
    51          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_DEBUG_TEST_ASSERT>;
    52          break;
    53      case SPINEL_PROP_DEBUG_TEST_WATCHDOG:
    54          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_DEBUG_TEST_WATCHDOG>;
    55          break;
    56      case SPINEL_PROP_DEBUG_NCP_LOG_LEVEL:
    57          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_DEBUG_NCP_LOG_LEVEL>;
    58          break;
    59      case SPINEL_PROP_HWADDR:
    60          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_HWADDR>;
    61          break;
    62      case SPINEL_PROP_HOST_POWER_STATE:
    63          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_HOST_POWER_STATE>;
    64          break;
    65      case SPINEL_PROP_INTERFACE_COUNT:
    66          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_INTERFACE_COUNT>;
    67          break;
    68      case SPINEL_PROP_INTERFACE_TYPE:
    69          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_INTERFACE_TYPE>;
    70          break;
    71      case SPINEL_PROP_LAST_STATUS:
    72          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_LAST_STATUS>;
    73          break;
    74      case SPINEL_PROP_LOCK:
    75          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_LOCK>;
    76          break;
    77      case SPINEL_PROP_PHY_ENABLED:
    78          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PHY_ENABLED>;
    79          break;
    80      case SPINEL_PROP_PHY_CHAN:
    81          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PHY_CHAN>;
    82          break;
    83      case SPINEL_PROP_PHY_RSSI:
    84          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PHY_RSSI>;
    85          break;
    86      case SPINEL_PROP_PHY_RX_SENSITIVITY:
    87          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PHY_RX_SENSITIVITY>;
    88          break;
    89      case SPINEL_PROP_PHY_TX_POWER:
    90          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PHY_TX_POWER>;
    91          break;
    92      case SPINEL_PROP_POWER_STATE:
    93          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_POWER_STATE>;
    94          break;
    95      case SPINEL_PROP_MCU_POWER_STATE:
    96          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_MCU_POWER_STATE>;
    97          break;
    98      case SPINEL_PROP_PROTOCOL_VERSION:
    99          handler = &NcpBase::HandlePropertyGet<SPINEL_PROP_PROTOCOL_VERSION>;
   100          break;
